				ILetter letter = new Letter(tagCompound);
				if (letter.getSender().getType() == EnumAddressee.PLAYER) {
					playerLetters++;
				} else {
					tradeLetters++;
				}
			}
		}

		return new POBoxInfo(playerLetters, tradeLetters);
	}

